if (root == nullptr) return 0;

std::queue<Node*> q;
q.push(root);
int currentLevel = 0;
int keyCount = 0;

while (!q.empty()) {
    int sz = static_cast<int>(q.size());

    if (currentLevel == level) {
        for (int i = 0; i < sz; ++i) {
            Node* u = q.front();
            q.pop();
            keyCount += static_cast<int>(u->keys.size());
        }
        return keyCount;
    }

    for (int i = 0; i < sz; ++i) {
        Node* u = q.front();
        q.pop();

        if (!u->isLeaf) {
            for (Node* v : u->ptr2TreeOrData.ptr2Tree) {
                if (v != nullptr) q.push(v);
            }
        }
    }
    ++currentLevel;
}
return 0;

